\label{2413lem1}
If $n \geq 4$, then
\begin{equation}\label{2413lem1e1}
u_{n,i}=u_{n-1,i}+\sum_{j=2}^{i-1}\sum_{m=0}^{n-i-1}u_{j+m,j}u_{n-m-j,i-j+1}, \qquad 3 \leq i \leq n-1,
\end{equation}
and
\begin{equation}\label{2413lem1e2}
v_{n,i}=v_{n-1,i}+\sum_{j=2}^{i-1}\sum_{m=0}^{i-j-1}v_{i-m-1,j}v_{n+m-i+1,m+2}, \qquad 3 \leq i \leq n-1,
\end{equation}
with $u_{n,2}=v_{n,2}=1$, $u_{n,n}=u_{n-1}$ and $v_{n,n}=v_{n-1}$ for all $n \geq 2$.

\label{2413lem2}
If $n \geq 3$, then
\begin{equation}\label{2413lem2e1}
u_n(y)=y^{n-1}u_{n-1}(1)+u_{n-1}(y)+\sum_{m=2}^{n-2}u_m(y)u_{n-m}(y)
\end{equation}
and
\begin{equation}\label{2413lem2e2}
v_n(y)=y^{n-1}v_{n-1}(1)+v_{n-1}(y)+\sum_{m=2}^{n-2}y^{n-m-1}v_m(y)v_{n-m}(1),
\end{equation}
with $u_1(y)=v_1(y)=1$ and $u_2(y)=v_2(y)=y$.

Multiplying both sides of \eqref{2413lem1e1} by $y^{i-1}$, and summing over $3 \leq i \leq n-1$, yields
\begin{align*}
u_n(y)&=y+u_{n-1}y^{n-1}+\sum_{i=3}^{n-1}u_{n-1,i}y^{i-1}+\sum_{i=3}^{n-1}y^{i-1}\sum_{j=2}^{i-1}\sum_{m=0}^{n-i-1}u_{j+m,j}u_{n-m-j,i-j+1}\\
&=y^{n-1}u_{n-1}(1)+u_{n-1}(y)+\sum_{j=2}^{n-2}\sum_{i=j+1}^{n-1}y^{i-1}\sum_{m=0}^{n-i-1}u_{j+m,j}u_{n-m-j,i-j+1}.
\end{align*}
Working on the preceding sum, we have
\begin{align*}
&\sum_{j=2}^{n-2}\sum_{i=j+1}^{n-1}y^{i-1}\sum_{m=0}^{n-i-1}u_{j+m,j}u_{n-m-j,i-j+1}\\
&=\sum_{j=2}^{n-2}\sum_{m=0}^{n-j-2}u_{j+m,j}\sum_{i=j+1}^{n-m-1}u_{n-m-j,i-j+1}y^{i-1}\\
&=\sum_{j=2}^{n-2}\sum_{m=0}^{n-j-2}u_{j+m,j}y^{j-1}\sum_{i=2}^{n-m-j}u_{n-m-j,i}y^{i-1}=\sum_{j=2}^{n-2}\sum_{m=0}^{n-j-2}y^{j-1}u_{j+m,j} u_{n-m-j}(y)\\
&=\sum_{j=2}^{n-2}\sum_{m=j}^{n-2}y^{j-1}u_{m,j}u_{n-m}(y)=\sum_{m=2}^{n-2}u_{n-m}(y)\sum_{j=2}^mu_{m,j}y^{j-1}=\sum_{m=2}^{n-2}u_m(y)u_{n-m}(y),
\end{align*}
which implies \eqref{2413lem2e1}. Formula \eqref{2413lem2e2} may be shown in a comparable manner starting with \eqref{2413lem1e2}.

\label{2413th1}
We have
\begin{equation}\label{2413th1e1}
U(x,y)=\frac{1+x-\sqrt{1-4x+x^2+2x\sqrt{1-4xy}}}{2}
\end{equation}
and
\begin{equation}\label{2413th1e2}
V(x,y)=\frac{x(3y-2+2x-2xy-y\sqrt{1-4xy})}{2(y-1+x)}.
\end{equation}

Multiplying both sides of \eqref{2413lem2e1} by $x^n$, and summing over all $n \geq3$, we obtain
\begin{align}
U(x,y)&=x+x^2y+x(U(xy,1)-xy)+x(U(x,y-x)+\sum_{n\geq4}x^n\sum_{m=2}^{n-2}u_m(y)u_{n-m}(y)\notag\\
&=x-x^2+x(U(xy,1)+U(x,y))+\sum_{m\geq2}u_m(y)\sum_{n\geq m+2}u_{n-m}(y)x^n\notag\\
&=x-x^2+x(U(xy,1)+U(x,y))+(U(x,y)-x)^2.\label{2413th1e3}
\end{align}
Taking $y=1$ in \eqref{2413th1e3} implies $p=U(x,1)$ satisfies $p^2-p+x$, and hence $p=\frac{1-\sqrt{1-4x}}{2}=xC$, where the choice of the negative root is dictated by the condition $U(0,1)=0$.  Substituting $U(xy,1)=\frac{1-\sqrt{1-4xy}}{2}$ into \eqref{2413th1e3} implies
$$U(x,y)^2-(1+x)U(x,y)+\frac{x}{2}\left(3-\sqrt{1-4xy}\right)=0,$$
and solving for $U(x,y)$ in the last equation gives \eqref{2413th1e1}.

Using \eqref{2413lem2e2}, one can show
\begin{equation}\label{2413th1e4}
V(x,y)=x-x^2+x(V(xy,1)+V(x,y))+\frac{1}{y}(V(x,y)-x)(V(xy,1)-xy).
\end{equation}
Taking $y=1$ in \eqref{2413th1e4} implies $V(x,1)=xC$, as before.  Substituting this back into \eqref{2413th1e4}, and solving for $V(x,y)$, leads to \eqref{2413th1e2} after some algebra.

\label{3142lem1}
If $n \geq 3$, then
\begin{equation}\label{3142lem1e1}
w_{n,i}=w_{i-2}w_{n-i+2}, \qquad 3 \leq i \leq n,
\end{equation}
with $w_{n,2}=w_{n-1}$ for $n\geq 2$.

Let $\mathcal{W}_{n,i}$ denote the subset of $\mathcal{W}_n$ whose members have second letter $i$ for $2 \leq i \leq n$.  Then members of  $\mathcal{W}_{n,2}$ are synonymous with those in $\mathcal{W}_{n-1}$, upon deletion of 2, which implies the initial condition for $i=2$.  Suppose now $\pi \in \mathcal{P}_n$ is expressible as
\begin{equation}\label{3142lem1e2}
\pi=1i\alpha2\beta\gamma,
\end{equation}
for some $i \in [3,n]$, where $\alpha$, $\beta$ or $\gamma$ may be empty, $\alpha$ is a subset of $[i+1,n]$ in increasing order, and the leftmost letter in $[i+1,n]$ occurring to the right of 2 within $\pi$ (if it exists) coincides with the first letter of $\gamma$.  Let $x$ denote the final letter of $2\beta$.  Then we have that $\pi$ of the form \eqref{3142lem1e2} avoids the pattern 3142 if and only if the subsequences $2\beta$ and $i\alpha x\gamma$ both avoid 3142, with $2\beta$ consisting of the letters in $[2,i-1]$. To see this, first note that no letter in $[3,i-1]$ can occur in $\gamma$,  whence these letters must all lie in $\beta$, for otherwise, there would be a 3142 as witnessed by $i2yz$, where $y$ denotes the first letter of $\gamma$ and $z$ is some letter in $\gamma$ that is less than $i$. Further, the letters in $\beta$ all being smaller than those in $\gamma$ rules out an occurrence of 3142 starting in $\beta$ and ending in $\gamma$.  Finally, by requiring that $i\alpha x \gamma$ avoid 3142, one rules out any occurrences of the pattern whose first letter lies to the left of 2 or to the right of $\beta$.

To enumerate members of $\mathcal{W}_{n,i}$ where $3 \leq i \leq n$, first note that there are clearly $w_{i-2}$ possibilities for $2\beta$.  Viewing $x$ as the second smallest letter within the 3142-avoiding flattened partition $i\alpha x\gamma$, one has that it represents an arbitrary member of $\mathcal{W}_{n-i+2}$.  Since the standardized forms of $2\beta$ and $i\alpha x\gamma$ in \eqref{3142lem1e2} may be chosen independently of one another, the equality \eqref{3142lem1e1} follows, which completes the proof.

\label{3142t1}
We have
\begin{equation}\label{3142t1e1}
W(x,y)=\frac{1-(1+2x)\sqrt{1-4x}-(1-2x)\sqrt{1-4xy}+\sqrt{(1-4x)(1-4xy)}}{4},
\end{equation}
and, in particular, $\sum_{n\geq 2}p_n(3142)x^n=W(x,1)=x(C-1)$.

By \eqref{3142lem1e1}, we have
\begin{align}
w_n(y)&=w_{n-1}+\sum_{i=3}^ny^{i-2}w_{i-2}w_{n-i+2}\notag\\
&=(1+y)w_{n-1}(1)+\sum_{i=2}^{n-2}y^iw_i(1)w_{n-i}(1), \qquad n \geq 3, \label{3142t1e2}
\end{align}
with $w_2(y)=1$. Multiplying both sides of \eqref{3142t1e2} by $x^n$, and summing over all $n \geq 3$, yields
\begin{align}
W(x,y)-x^2&=(1+y)\sum_{n\geq 3}w_{n-1}(1)x^n+\sum_{n\geq 4}x^n\sum_{i=2}^{n-2}y^iw_i(1)w_{n-i}(1) \notag\\
&=x(1+y)W(x,1)+\sum_{i\geq2}y^iw_i(1)\sum_{n\geq i+2}w_{n-i}(1)x^n\notag\\
&=x(1+y)W(x,1)+W(x,1)W(xy,1). \label{3142t1e3}
\end{align}
Taking $y=1$ in \eqref{3142t1e3} implies $p=W(x,1)$ satisfies $p^2-(1-2x)p+x^2=0$, and hence $p=x(C-1)$.  Substituting this back into \eqref{3142t1e3}, and simplifying, yields \eqref{3142t1e1} and completes the proof.

\label{2143lem1}
If $n \geq 3$, then
\begin{equation}\label{2143lem1e1}
a_{n,i}=\sum_{j=0}^{n-i}\binom{n-i}{j}a_{n-j,i}^*, \qquad 3 \leq i \leq n,
\end{equation}
with $a_{n,2}=a_{n-1}$ for all $n \geq 2$.  If $n \geq 5$, then
\begin{equation}\label{2143lem1e2}
a_{n,i}^*=\sum_{m=0}^{n-i}a_{n-m-1,i-1}^*+\sum_{k=4}^{i-1}\sum_{j=0}^{i-k-1}\sum_{m=0}^{n-i}\binom{i-k-1}{j}a_{n-j-m-2,k-1}^*, \quad 4 \leq i \leq n-1,
\end{equation}
with $a_{n,3}^*=1$ and $a_{n,n}^*=a_{n-2}$ for $n \geq 3$.

\label{2143lem2}
We have
\begin{align}
A(x,v)&=x^2+xA(x,1)+v(1-x)^2B\left(\frac{x}{1-x},v(1-x)\right)\label{2143lem2e1}
\end{align}
and
\begin{align}
&\left(1-\frac{vx}{1-x}-\frac{v^2x^2}{(1-x)(1-v-vx)}\right)B(x,v)\notag\\
&=\frac{x^3}{1-x}-vx^4+\frac{x^2}{v}(1-vx)A(vx,1)-x^2(1-vx)^2\left(\frac{1}{(1-x)(1-v-vx)}+\frac{1}{v}\right)B\left(\frac{vx}{1-vx},1-vx\right).\label{2143lem2e2}
\end{align}

By \eqref{2143lem1e1}, we have
$$A(x,v)-\sum_{n\geq 3}a_{n-1}x^n-x^2=\sum_{n\geq3}x^n\sum_{i=3}^nv^{i-2}\sum_{j=0}^{n-i}\binom{n-i}{j}a_{n-j,i}^*,$$
and hence
\begin{align*}
A(x,v)-xA(x,1)-x^2&=\sum_{i\geq3}v^{i-2}\sum_{n\geq i}x^n\sum_{j=i}^n\binom{n-i}{n-j}a_{j,i}^*=\sum_{i\geq3}\sum_{j\geq i}a_{j,i}^*v^{i-2}\sum_{n\geq j}\binom{n-i}{j-i}x^n\\
&=\sum_{i\geq3}\sum_{j\geq i}a_{j,i}^*v^{i-2}\cdot \frac{x^i}{(1-x)^{j-i+1}}=\sum_{j\geq3}\frac{x^j}{(1-x)^j}\sum_{i=3}^ja_{j,i}^*v^{i-2}(1-x)^{i-1}\\
&=v(1-x)^2B\left(\frac{x}{1-x},v(1-x)\right),
\end{align*}
which yields \eqref{2143lem2e1}.

By \eqref{2143lem1e2}, we have
\begin{align*}
&B(x,v)-\frac{x^3}{1-x}-\frac{x^2}{v}A(vx,1)=\sum_{n\geq5}\sum_{i=4}^{n-1}a_{n,i}^*v^{i-3}x^n\\
&=\sum_{n\geq5}\sum_{i=4}^{n-1}\Bigg(
  a_{n-1, i-1}^*
  + \sum_{m=1}^{n-i} a^*_{n-m-1, i-1}
  + \sum_{k=4}^{i-1}
      \sum_{j=0}^{i-k-1}
      \sum_{m=0}^{n-i}
        \binom{i-k-1}{j}
        a_{n-j-m-2, k-1}^*\Bigg)v^{i-3}x^{n}\\
&=vx\left(B(x,v)-\frac{x^2}{v}A(vx,1)-x^3\right)\\
&\quad+\sum_{n\geq5}
\sum_{i=4}^{n-1}
\Bigg(
    \sum_{m=1}^{\,n-i}
        a_{n-m-1, i-1}^* v^{i-3}x^{n}
    +
    \sum_{k=4}^{i-1}
        \sum_{j=0}^{i-k-1}
        \sum_{m=0}^{n-i}
            \binom{i-k-1}{j}
            a_{n-j-m-2, k-1}^*
            v^{i-3}x^{n}\Bigg).\\
\end{align*}
Working separately on the last two multi-sum expressions, we get
\begin{align*}
&\sum_{n\geq5}\sum_{i=4}^{n-1}\sum_{m=1}^{\,n-i}a_{n-m-1, i-1}^* v^{i-3}x^{n}=\sum_{i\geq4}\sum_{n\geq i+1}\sum_{m=i}^{n-1}a_{m-1,i-1}^*v^{i-3}x^n\\
&=\sum_{i\geq4}\sum_{m\geq i}a_{m-1,i-1}^*v^{i-3}\cdot\frac{x^{m+1}}{1-x}=\frac{x}{1-x}\sum_{m\geq4}\sum_{i=4}^ma_{m-1,i-1}^*v^{i-3}x^m=\frac{vx^2}{1-x}B(x,v)
\end{align*}
and
\begin{align*}
&\sum_{n\geq5}\sum_{i=4}^{n-1}\sum_{k=4}^{i-1}\sum_{j=0}^{i-k-1}\sum_{m=0}^{n-i}\binom{i-k-1}{j}a_{n-j-m-2, k-1}^*v^{i-3}x^{n}\\
&=\sum_{k\geq4}\sum_{i\geq1}\sum_{n\geq i+k+1}\sum_{j=0}^{i-1}\sum_{m=0}^{n-i-k}\binom{i-1}{j}a_{n-j-m-2,k-1}^*v^{i+k-3}x^n\\
&=\sum_{k\geq3}\sum_{i\geq1}\sum_{n\geq k+2}\sum_{j=0}^{i-1}\sum_{m=0}^{n-k-1}\binom{i-1}{j}a_{n+i-j-m-2,k}^*v^{i+k-2}x^{n+i}\\
&=\sum_{k\geq3}\sum_{n\geq k+2}\sum_{j\geq0}\sum_{i\geq1}\sum_{m=0}^{n-k-1}\binom{i+j-1}{j}a_{n+i-m-2,k}^*v^{i+j+k-2}x^{n+i+j}\\
&=\sum_{k\geq3}\sum_{i\geq1}\sum_{n\geq i+k+2}\sum_{m=0}^{n-i-k-1}a_{n-m-2,k}^*v^{i+k-2}x^n\sum_{j\geq0}\binom{i+j-1}{j}(vx)^j\\
&=\sum_{k\geq3}\sum_{i\geq1}\sum_{n\geq i+k+2}\sum_{m=i+k-1}^{n-2}\frac{a_{m,k}^*v^{i+k-2}x^n}{(1-vx)^i}.
\end{align*}

This last sum may be written as the difference of two sums as
\begin{align*}
&\sum_{k\geq3}\sum_{i\geq1}\sum_{n\geq i+k+1}\sum_{m=i+k-1}^{n-2}\frac{a_{m,k}^*v^{i+k-2}x^n}{(1-vx)^i}-\sum_{k\geq3}\sum_{i\geq1}\frac{a_{i+k-1,k}^*v^{i+k-2}x^{i+k+1}}{(1-vx)^i}\\
&=\sum_{k\geq3}\sum_{i\geq1}\sum_{m\geq i+k-1}\frac{a_{m,k}^*v^{i+k-2}x^{m+2}}{(1-x)(1-vx)^i}-\sum_{k\geq3}\sum_{i \geq k}\frac{a_{i,k}^*v^{i-1}x^{i+2}}{(1-vx)^{i-k+1}}\\
&=\sum_{k\geq3}\sum_{m\geq k}\frac{a_{m,k}^*v^{k-1}x^{m+2}}{1-x}\cdot\frac{1-\left(\frac{v}{1-vx}\right)^{m-k+1}}{1-v-vx}-\frac{x^2}{v}\sum_{i\geq3}\sum_{k=3}^ia_{i,k}^*\left(\frac{vx}{1-vx}\right)^i(1-vx)^{k-1}\\
&=\frac{v^2x^2}{(1-x)(1-v-vx)}\sum_{m\geq3}\sum_{k=3}^ma_{m,k}^*v^{k-3}x^m\left(1-\left(\frac{v}{1-vx}\right)^{m-k+1}\right)-\frac{x^2}{v}(1-vx)^2B\left(\frac{vx}{1-vx},1-vx\right)\\
&=\frac{v^2x^2}{(1-x)(1-v-vx)}\left(B(x,v)-\frac{(1-vx)^2}{v^2}B\left(\frac{vx}{1-vx},1-vx\right)\right)-\frac{x^2}{v}(1-vx)^2B\left(\frac{vx}{1-vx},1-vx\right).
\end{align*}
Combining with the prior computations, we get
\begin{align*}
&B(x,v)-\frac{x^3}{1-x}-\frac{x^2}{v}A(vx,1)\\
&=\frac{vx}{1-x}B(x,v)-x^3A(vx,1)-vx^4+\frac{v^2x^2}{(1-x)(1-v-vx)}B(x,v)\\
&\quad-x^2(1-vx)^2\left(\frac{1}{(1-x)(1-v-vx)}+\frac{1}{v}\right)B\left(\frac{vx}{1-vx},1-vx\right),
\end{align*}
which may be rewritten as \eqref{2143lem2e2}.

\label{2314lem1}
If $n \geq 3$, then
\begin{equation}\label{2314l1e1}
b_{n,i,j}=\sum_{k=0}^{i-j-1}\sum_{s=1}^{j-1}\binom{i-j-1}{k}b_{n-k-1,s,i-k-1}, \quad 2 \leq j< i \leq n,
\end{equation}
\begin{equation}\label{2314l1e2}
b_{n,i,i+1}=\sum_{s=1,s\neq i}^{n-1}b_{n-1,s,i}, \qquad 2 \leq i \leq n-1,
\end{equation}
and
\begin{equation}\label{2314l1e3}
b_{n,i,j}=\sum_{m=0}^1\sum_{s=1}^{i-1}b_{n-m-1,s,j-m-1}+\sum_{m=0}^1\sum_{r=j+1}^n\sum_{k=0}^{r-j-1}\sum_{s=1}^{i-1}\binom{r-j-1}{k}b_{n-k-m-2,s,r-k-m-2},
\end{equation}
for $2 \leq i<j-1 \leq n-1$.

\label{2314lem2}
We have
\small\begin{align}
B_-(x,u,v)&=\frac{u^2x}{v(1-v+ux)}\left(\frac{1}{v-ux}B_+\left(x,u,\frac{u}{v-ux}\right)-B_+(x,u,u)\right),\label{2314lem2e1}\\
 B_+(x,u,v)&=x^2+\frac{uvx}{u-v}(B_+(x,u,u)-B_+(x,u,v))+\frac{uvx^2}{u-v}(uB_+(x,u,u)-vB_+(x,u,v))\notag\\ &\quad+\frac{ux^2}{(1-v+vx)(1-u+ux)(u-v)}\biggl(v(uvx-uv-u+v)\left(B_+(x,u,v)-B_+\left(x,u,\frac{1}{1-x}\right)\right)\notag\\
&\qquad\qquad\qquad+uv\left(B_+(x,u,v)-v(1-x)B_+\left(x,u,\frac{1}{1-x}\right)\right)-uv(1-v+vx)B_+(x,u,u)\biggr)\notag\\ &\quad+\frac{uvx^3}{(1-v+vx)(1-u+ux)(u-v)}\biggl((uvx-uv-u+v)\left(vB_+(x,u,v)-\frac{1}{1-x}B_+\left(x,u,\frac{1}{1-x}\right)\right)\notag\\
&\qquad\qquad\qquad+uv\left(B_+(x,u,v)-B_+\left(x,u,\frac{1}{1-x}\right)\right)-u^2(1-v+vx)B_+(x,u,u)\biggr)\notag\\
&\quad+ux(B_-(x,u,u)+B_+(x,u,u)). \label{2314lem2e2}\normalsize
\end{align}

\label{2314thm}
The generating function $B(x,u,v)$ equals
\begin{equation}\label{2314thme1}
B_+(x,u,v)+\frac{u^2x}{v(1-v+ux)}\left(\frac{1}{v-ux}B_+\left(x,u,\frac{u}{v-ux}\right)-B_+(x,u,u)\right),
\end{equation}
where $B_+(x,u,v)$ is given by \eqref{2314b}.

\label{2314thm2}
The generating function $B(x,u,v)$ is  given by \eqref{2314thme1},
where
\begin{align*}
B_+(x,u,v)&=
\frac{
x (u x + 1)
\bigl(
u v^{2} v_{0} x^{2}
+ u v v_{0}^{2} x^{2}
- u v v_{0} x^{2}
+ u v v_{0} x
+ v v_{0} x
- v v_{0}
+ u
\bigr)
}{
\bigl(u v_{0}^{2} x^{2} - u v_{0} x^{2} - u x + v_{0} x - v_{0}\bigr)
\bigl(u v^{3} x^{2} - u v^{2} x^{2} + u v^{2} x - 2 u v x + v^{2} x + u v - v^{2} - u + v\bigr)
}.
\end{align*}

\label{3214lem1}
If $n \geq 3$, then
\begin{equation}\label{3214l1e1}
d_{n,i,j}=\sum_{k=0}^{i-j-1}\sum_{s=1}^{j-1}\binom{i-j-1}{k}d_{n-k-1,s,i-k-1}, \quad 2 \leq j< i \leq n,
\end{equation}
\begin{equation}\label{3214l1e2}
d_{n,i,i+1}=\sum_{s=1,s\neq i}^{n-1}d_{n-1,s,i}, \qquad 2 \leq i \leq n-1,
\end{equation}
and
\begin{equation}\label{3214l1e3}
d_{n,i,j}=\sum_{m=0}^{j-i-1}\sum_{s=1}^{i-1}d_{n-m-1,s,j-m-1}+\sum_{m=0}^{j-i-1}\sum_{r=j+1}^n\sum_{k=0}^{r-j-1}\sum_{s=1}^{i-1}\binom{r-j-1}{k}d_{n-k-m-2,s,r-k-m-2},
\end{equation}
for $2 \leq i<j-1 \leq n-1$.

\label{3214l2}
We have
\begin{align}
D_-(x,u,v)&=\frac{u^2x}{v(1-v+ux)}\left(\frac{1}{v-ux}D_+\left(x,u,\frac{u}{v-ux}\right)-D_+(x,u,u)\right), \label{3214l2e1}\\
D_+(x,u,v)&= x^2+ux(D_-(x,u,u)+D_+(x,u,u))\notag\\
&\quad+\frac{ux}{(1-vx)(u-v)}(uD_+(x,u,u)-vD_+(x,u,v))-uxD_+(x,u,u)\notag\\
&\quad+\frac{x^2}{(1-vx)(u-v)}\biggl(\frac{u^2}{(1-x)(1-u+ux)}
\left(D_+\left(x,u,\frac{1}{1-x}\right)-u(1-x)D_+(x,u,u)\right)\notag\\
&\quad+\frac{uv}{(1-x)(1-v+vx)}\left(v(1-x)D_+(x,u,v)-D_+\left(x,u,\frac{1}{1-x}\right)\right)\biggr)\notag\\
&\quad-\frac{ux^2}{(1-x)(1-u+ux)}\left(D_+\left(x,u,\frac{1}{1-x}\right)-u(1-x)D_+(x,u,u)\right). \label{3214l2e2}
\end{align}

\label{3214thm2}
We have $$D(x,u,v)=D_+(x,u,v)+\frac{u^2x}{v(1-v+ux)}\left(\frac{1}{v-ux}D_+\left(x,u,\frac{u}{v-ux}\right)-D_+(x,u,u)\right),$$ where
\begin{align*}
D_+(x,u,v)=\frac{x^2 (v x - v_0 x + u - v + v_0)
          (u v v_0 x^2 - v^2 v_0 x^2 - v v_0^2 x^2 + v^2 v_0 x + v v_0^2 x - v v_0 + u)}{v_0(x-1)(u v^2 x^2 - v^3 x^2 + v^3 x - u v x + u v - v^2 - u + v)}.
\end{align*}

\label{3214cor}
The generating function $\sum_{n\geq 2}p_n(3214)x^n$ is given by $$D(x,1,1)=\frac{x(1-x-\sqrt{1-6x+5x^2})}{2(1-x)},$$
and hence $p_n(3214)=\sum_{k=0}^{n-2}\binom{n-2}{k}C_k$ for all $n \geq 2$.

\label{4213lem1}
We have
\begin{equation}\label{4213lem1e1}
e_n=1+\sum_{i=3}^ne_{n,i}, \qquad n \geq 3,
\end{equation}
\begin{equation}\label{4213lem1e2}
e_{n,i}=\sum_{j=0}^{i-3}\binom{i-2}{j}e_{n-j,i-j}^*, \qquad 3 \leq i \leq n,
\end{equation}
and
\begin{equation}\label{4213lem1e3}
e_{n,i}^*=\sum_{m=1}^{i-3}e_{n-m,i-m}^*+\sum_{k=i+1}^n\sum_{j=0}^{k-i-1}\sum_{m=2}^{i-2}\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*, \qquad 5 \leq i \leq n-1,
\end{equation}
with $e_1=e_2=1$,  $e_{n,3}^*=e_{n-2}$ for $n \geq 3$, $e_{n,4}^*=e_{n-2}$ and $e_{n,n}^*=2^{n-4}$ for $n \geq 4$.  Moreover, the same recurrences and initial conditions are seen to hold if the arrays $e_{n,i}$ and $e_{n,i}^*$ are defined in conjunction with the pattern 4312 instead of 4213, and hence, in particular, $p_n(4312)=p_n(4213)$ for all $n \geq 1$

\label{4213lem2}
We have
\begin{align}
G(x)&=\frac{x^2}{1-x}+E(x,1), \label{4213lem2e1}\\
E(x,v)&=\frac{1}{(1-vx)^2}F\left(x,\frac{v}{1-vx}\right), \label{4213lem2e2}\\
\left(1-\frac{vx}{1-vx}+\frac{v^2x^2}{(1-vx)(1-v+vx)}\right)F(x,v)&=x^3(1-vx)+x^2(1+v-vx)G(x)\notag\\
&\quad+\frac{vx^2}{1-x}\left(\frac{1}{(1-vx)(1-v+vx)}-1\right)F\left(x,\frac{1}{1-x}\right).\label{4213lem2e3}
\end{align}

Equation \eqref{4213lem2e1} follows from \eqref{4213lem1e1} and the definitions of the respective generating functions.  From \eqref{4213lem1e2}, we get
\begin{align*}
E(x,v)&=\sum_{n\geq3}\sum_{i=3}^n\sum_{j=0}^{i-3}\binom{i-2}{j}e_{n-j,i-j}^*v^{i-3}x^n=\sum_{j\geq0}\sum_{n \geq j+3}\sum_{i=j+3}^n\binom{i-2}{j}e_{n-j,i-j}^*v^{i-3}x^n\\
&=\sum_{j\geq0}\sum_{n\geq3}\sum_{i=3}^n\binom{i+j-2}{j}e_{n,i}^*v^{i+j-3}x^{n+j}\\
&=\sum_{n\geq3}\sum_{i=3}^ne_{n,i}^*v^{i-3}x^n\cdot\frac{1}{(1-vx)^{i-1}}=\frac{1}{(1-vx)^2}F\left(x,\frac{v}{1-vx}\right),
\end{align*}
which yields \eqref{4213lem2e2}.  For \eqref{4213lem2e3}, first note that by the formulas for $e_{n,i}^*$ when $i=2,\,3\,$ or $n$, we have
\begin{align}
\sum_{n\geq6}\sum_{i=5}^{n-1}e_{n,i}^*v^{i-3}x^n&=F(x,v)-\sum_{n\geq3}e_{n-2}x^n-v\sum_{n\geq4}e_{n-2}x^n-\sum_{n\geq5}2^{n-4}v^{n-3}x^n\notag\\
&=F(x,v)-x^3-x^2(1+v)G(x)-\frac{2v^2x^5}{1-2vx}. \label{4213lem2e4}
\end{align}

On the other hand, multiplying both sides of \eqref{4213lem1e3} by $v^{i-3}x^n$, and summing over all $5 \leq i \leq n-1$, we get
\begin{align}
\sum_{n\geq6}\sum_{i=5}^{n-1}e_{n,i}^*v^{i-3}x^n&=\sum_{n\geq6}\sum_{i=5}^{n-1}\sum_{m=1}^{i-3}e_{n-m,i-m}^*v^{i-3}x^n\notag\\
&\quad+\sum_{n\geq6}\sum_{i=5}^{n-1}\sum_{k=i+1}^n\sum_{j=0}^{k-i-1}\sum_{m=2}^{i-2}\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*v^{i-3}x^n. \label{4213lem2e5}
\end{align}
Working separately on the last two sums, we have that the first sum is given by
\begin{align*}
\sum_{n\geq6}\sum_{i=5}^{n-1}\sum_{m=1}^{i-3}e_{n-m,i-m}^*v^{i-3}x^n&=\sum_{n \geq 6}\sum_{m=1}^{n-4}\sum_{i=m+3}^{n-1}e_{n-m,i-m}^*v^{i-3}x^n-v\sum_{n\geq6}e_{n-1,3}^*x^n\\
&=\sum_{m\geq1}\sum_{n \geq m+4}\sum_{i=m+3}^{n-1}e_{n-m,i-m}^*v^{i-3}x^n-v\sum_{n\geq5}e_{n-1,3}^*x^n\\
&=\sum_{m\geq1}\sum_{n\geq4}\sum_{i=3}^{n-1}e_{n,i}^*v^{i+m-3}x^{n+m}-v\sum_{n\geq5}e_{n-3}x^n
\end{align*}
\begin{align*}
\qquad\qquad\qquad\qquad&=\sum_{n\geq4}\sum_{i=3}^{n-1}e_{n,i}^*v^{i-3}x^n\cdot \frac{vx}{1-vx}-vx^3G(x)\\
&=\frac{vx}{1-vx}\left(F(x,v)-x^3-\frac{vx^4}{1-2vx}\right)-vx^3G(x).
\end{align*}

For the second sum on the right side of \eqref{4213lem2e5}, we get
\begin{align*}
&\sum_{n\geq6}\sum_{i=5}^{n-1}\sum_{k=i+1}^n\sum_{j=0}^{k-i-1}\sum_{m=2}^{i-2}\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*v^{i-3}x^n\\
&=\sum_{n \geq 6}\sum_{j=0}^{n-6}\sum_{i=5}^{n-j-1}\sum_{m=2}^{i-2}\sum_{k=i+j+1}^n\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*v^{i-3}x^n\\
&=\sum_{j\geq0}\sum_{n\geq j+6}\sum_{m=2}^{n-j-3}\sum_{i=m+2}^{n-j-1}\sum_{k=i+j+1}^n\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*v^{i-3}x^n-S,
\end{align*}
where $S=v\sum_{j\geq0}\sum_{n\geq j+6}\sum_{k=j+5}^n\binom{k-5}{j}e_{n-j-2,k-j-2}x^n$, upon adding and subtracting to the summation the case when $i=4$.  Considering separately the cases when $m\geq 3$ or $m=2$, one obtains
\begin{align*}
&\sum_{j\geq0}\sum_{m\geq3}\sum_{n\geq j+m+3}\sum_{i=m+2}^{n-j-1}\sum_{k=i+j+1}^n\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*v^{i-3}x^n\\
&\quad+\sum_{j\geq0}\sum_{n\geq j+6}\sum_{i=4}^{n-j-1}\sum_{k=i+j+1}^n\binom{k-i-1}{j}e_{n-j-2,k-j-2}^*v^{i-3}x^n-S\\
&=\sum_{j\geq0}\sum_{m\geq3}\sum_{i \geq m+2}\sum_{n\geq i+j+1}\sum_{k=i+j+1}^n\binom{k-i-1}{j}e_{n-m-j,k-m-j}^*v^{i-3}x^n\\
&\quad+\sum_{j\geq0}\sum_{i \geq 5}\sum_{n \geq i+j+1}\sum_{k=i+j+1}^n\binom{k-i-1}{j}e_{n-j-2,k-j-2}^*v^{i-3}x^n\\
&=\sum_{j\geq0}\sum_{m\geq3}\sum_{i \geq2}\sum_{n \geq i+1}\sum_{k=i+1}^n\binom{k+j-i-1}{j}e_{n,k}^*v^{i+m-3}x^{n+m+j}\\
&\quad+\sum_{j\geq0}\sum_{i \geq 5}\sum_{n \geq i-1}\sum_{k=i-1}^n\binom{k+j-i+1}{j}e_{n,k}^*v^{i-3}x^{n+j+2}\\
&=\frac{x^3}{1-vx}\sum_{i\geq2}\sum_{n\geq i+1}\sum_{k=i+1}^ne_{n,k}^*v^ix^n\cdot\frac{1}{(1-x)^{k-i}}+\sum_{i\geq 5}\sum_{n \geq i-1}\sum_{k=i-1}^ne_{n,k}^*v^{i-3}x^{n+2}\cdot\frac{1}{(1-x)^{k-i+2}}.
\end{align*}

Interchanging the sum in $i$ with the others now gives
\begin{align*}
&\frac{x^3}{1-vx}\sum_{n\geq 3}\sum_{k=3}^ne_{n,k}^*\frac{x^n}{(1-x)^k}\sum_{i=2}^{k-1}(v(1-x))^i+\sum_{n\geq4}\sum_{k=4}^ne_{n,k}^*\frac{x^{n+2}}{v(1-x)^k}\sum_{i=5}^{k+1}(v(1-x))^{i-2}\\
&=\frac{x^3}{1-vx}\sum_{n\geq 3}\sum_{k=3}^ne_{n,k}^*\frac{x^n}{(1-x)^k}\cdot\frac{(v(1-x))^2-(v(1-x))^k}{1-v+vx}\\
&\quad+\sum_{n\geq3}\sum_{k=3}^ne_{n,k}^*\frac{x^{n+2}}{v(1-x)^k}\cdot\frac{(v(1-x))^3-(v(1-x))^k}{1-v+vx}\\
&=\frac{v^2x^3}{(1-vx)(1-v+vx)}\left(\frac{1}{1-x}F\left(x,\frac{1}{1-x}\right)-vF(x,v)\right)+\frac{v^2x^2}{1-v+vx}\left(F\left(x,\frac{1}{1-x}\right)-F(x,v)\right).\\
\end{align*}
Comparing \eqref{4213lem2e4} and \eqref{4213lem2e5}, and combining the prior calculations, we have
\begin{align*}
&F(x,v)-x^3-x^2(1+v)G(x)-\frac{2v^2x^5}{1-2vx}\\
&=\frac{vx}{1-vx}\left(F(x,v)-x^3-\frac{vx^4}{1-2vx}\right)-vx^3G(x)\\
&\quad+\frac{v^2x^3}{(1-vx)(1-v+vx)}\left(\frac{1}{1-x}F\left(x,\frac{1}{1-x}\right)-vF(x,v)\right)+\frac{v^2x^2}{1-v+vx}\left(F\left(x,\frac{1}{1-x}\right)-F(x,v)\right).
\end{align*}
The last equality may be rewritten as \eqref{4213lem2e3}, which completes the proof.

\label{4213th}
We have
\begin{align}
E(x,v)&=\frac{x^3(1-v-3vx+2v^2x+v^2x^2)+x^2(1-3vx+v^2x+v^2x^2)G(x)}{(1-vx)^2(1-v-3vx+3v^2x+v^2x^2)},\label{4213the0}
\end{align}
where $G(x)=\frac{x(1-x-\sqrt{1-6x+5x^2})}{2(1-x)}$.  In particular, the formula for the generating function $\sum_{n\geq2}p_n(\tau)x^n$, where $\tau \in \{4213,4312\}$, is given by $G(x)=E(x,1)+\frac{x^2}{1-x}$.

The second statement follows from the first, upon taking $v=1$, so we need only prove the first.  By \eqref{4213lem2e2} when $v=1$ and \eqref{4213lem2e1}, we have
\begin{equation}\label{4213the1}
F\left(x,\frac{1}{1-x}\right)=(1-x)^2G(x)-x^2(1-x).
\end{equation}
Substituting \eqref{4213the1} into \eqref{4213lem2e3}, and simplifying, we get
\begin{align}
\left(1-\frac{vx}{1-vx}+\frac{v^2x^2}{(1-vx)(1-v+vx)}\right)F(x,v)&=\frac{x^3(1-vx)(1-v+vx)-vx^4}{(1-vx)(1-v+vx)}\notag\\
&\quad+\frac{x^2((1-vx)(1-v+vx)+v-vx)}{(1-vx)(1-v+vx)}G(x). \label{4213the2}
\end{align}
Taking $v=v_0=\frac{1+x-\sqrt{1-6x+5x^2}}{2x(2-x)}$ in \eqref{4213the2} is seen to cancel out the left-hand side, and solving for $G(x)$, we find
$$G(x)=-\frac{x(1-v_0x)(1-v_0+v_0x)-v_0x^2}{(1-v_0x)(1-v_0+v_0x)+v_0(1-x)}.$$
Using the relation $(1-v_0x)(1-v_0+v_0x)=v_0x(1-v_0)$ gives
$$G(x)=-\frac{v_0x^2(1-v_0)-v_0x^2}{v_0x(1-v_0)+v_0(1-x)}=\frac{v_0x^2}{1-v_0x}=\frac{x(1-x-\sqrt{1-6x+5x^2})}{2(1-x)}.$$
Note that the choice of the minus sign prior to the radical term in $v_0$ is dictated by the requirement that $G(x)/x$ evaluated at $x=0$ be zero. Substituting this expression for $G(x)$ back into \eqref{4213the2}, solving for $F(x,v)$ and using \eqref{4213lem2e2} yields \eqref{4213the0}, which completes the proof.

\label{othercases}
Let $r_n=p_n(3124)$, $s_n=p_n(4123)$ and $t_n=p_n(2134)$ for $n \geq 1$.  Then we have
\begin{equation}\label{3124te1}
r_n=5r_{n-1}-8r_{n-2}+5r_{n-3}, \qquad n \geq 5,
\end{equation}
\begin{equation}\label{4123te1}
s_n=4s_{n-1}-4s_{n-2}+2s_{n-3}, \qquad n \geq 5,
\end{equation}
and
\begin{equation}\label{2134te1}
\sum_{n\geq 2}t_nx^n=\frac{(1-x)(1-3x+x^2-x^3)-(1-x)^2\sqrt{1-4x+2x^2+x^4}}{2x^2},
\end{equation}
where $r_n$ and $s_n$ satisfy the same initial conditions $r_1=r_2=1$, $r_3=2$, $r_4=5$.

We demonstrate only \eqref{3124te1} and outline its proof as follows.  Given $n \geq 2$ and $i,j \in [n]$ with $i \neq j$, let $r_{n,i,j}$ denote the number of members of $\mathcal{P}_n(3124)$ ending in $i,j$.  Then one can argue combinatorially the recurrences
\begin{align}
r_{n,i,j}&=\sum_{m=0}^{i-j-1}\sum_{s=1}^{j-1}r_{n-m-1,s,i-m-1}, \quad 2 \leq j< i \leq n, \label{2134e1}\\
r_{n,i,i+1}&=\sum_{s=1,s\neq i}^{n-1}r_{n-1,s,i}, \qquad 2 \leq i \leq n-1, \label{2134e2}\\
r_{n,i,j}&=\sum_{k=j}^n\sum_{s=1}^{i-1}r_{n-k+i,s,i}, \qquad 2 \leq i<j-1\leq n-1,\label{2134e3}
\end{align}
with $r_{2,1,2}=1$, $r_{2,2,1}=0$ and $r_{n,i,1}=r_{n,1,j}=0$ for all $i$ and $j$ if $n \geq 3$. Define the generating functions $$R_+(x,u,v)=\sum_{n\geq2}\sum_{i=1}^{n-1}\sum_{j=i+1}^{n}r_{n,i,j}u^{i-1}v^{j-i-1}x^n$$ and $$R_-(x,u,v)=\sum_{n\geq2}\sum_{i=2}^n\sum_{j=1}^{i-1}r_{n,i,j}u^{i-1}v^{j-i-1}x^n.$$
Translating \eqref{2134e1}--\eqref{2134e3}, we have
\begin{align}
R_+(x,u,v)&=x^2+ux(R_+(x,u,u)+R_-(x,u,u))+\frac{uvx^2}{(1-x)(1-vx)}R_+(x,u,u),\label{eq1p1}\\
R_-(x,u,v)&=\frac{u^2x}{v(1-v)(v-ux)}(R_+(x,u,u/v)-vR_+(x,u,u)).\label{eq1p2}
\end{align}

Using \eqref{eq1p2} in \eqref{eq1p1} yields
\begin{align}
R_+(x,u,v)&=x^2+\frac{ux^2}{(1-u)(1-x)}(R_+(x,u,1)-uR_+(x,u,u))+uxR_+(x,u,u)\nonumber\\
&\quad+\frac{uvx^2}{(1-x)(1-vx)}R_+(x,u,u).\label{eqp3}
\end{align}
First letting $v=1$ and then $v=u$ in \eqref{eqp3}, one obtains a system of equations in the quantities $R_+(x,u,1)$ and $R_+(x,u,u)$. Solving this system yields
\begin{align*}
R_+(x,u,1)&=-\frac{x^2(x-1)(u^2 x^2 + u x^3 - 3u x^2 + u x - x^2 + 2x - 1)}{u^2 x^4 - u x^4 + 4u x^3 - 5u x^2 + x^3 + 2u x - 3x^2 + 3x - 1},\\
R_+(x,u,u)&=-\frac{x^2(x-1)^3(u x - 1)}
{u^2 x^4 - u x^4 + 4u x^3 - 5u x^2 + x^3 + 2u x - 3x^2 + 3x - 1}.
\end{align*}
Taking $v=u$ in \eqref{eq1p2}, and using these last two expressions, we find
$$R_-(x,u,u)=\frac{x^3(u x^3 - 3u x^2 + u x - x^2 + 2x - 1)}
{u^2 x^4 - u x^4 + 4u x^3 - 5u x^2 + x^3 + 2u x - 3x^2 + 3x - 1}.$$

By the definitions, the generating function $\sum_{n\geq1}r_nx^n$ is given by
$$x+R_+(x,1,1)+R_-(x,1,1)=\frac{x(2x-1)(x-1)^2}{5x^3-8x^2+5x-1},$$
which implies recurrence \eqref{3124te1} and recovers the initial values of $r_n$.  Comparable proofs may be given for \eqref{4123te1} and \eqref{2134te1}, upon considering the parameters and distributions used above in the respective cases 4213 and 2143.  Note that from \eqref{4123te1} and \eqref{2134te1}, one obtains new combinatorial interpretations of the OEIS sequences A159035 and A273900, respectively.
